if\s*\(\s*[^)]*\b(m_enabled|enabled)\b[^)]*&&\s*\(\s*[^)]*linear\s*\.\s*x\s*!=\s*0[^)]*\|\|[^)]*angular\s*\.\s*z\s*!=\s*0[^)]*\)\s*\)

